/bin/bash -lc "python3 -c \"from pathlib import Path
subs=['codex-implementer','cursor-implementer','_implementer-base']
for root in ['python','scripts','agents']:
  for p in Path(root).rglob('*'):
    if p.is_file() and p.suffix in {'.py','.sh','.md'}:
      try: text=p.read_text(errors='ignore')
      except Exception: continue
      if any(s in text for s in subs):
        for i,line in enumerate(text.splitlines(),1):
          if any(s in line for s in subs): print(f'{p}:{i}:{line[:180]}')\""

